import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { createServiceRoleSupabaseClient } from '@/lib/supabase/server';
import { sendEmail } from '@/lib/email';
import { applyRateLimit } from '@/lib/api-middleware';
import { logger } from '@/lib/logger';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const bodySchema = z.object({ email: z.email().max(254) });
const GENERIC_MESSAGE = 'Falls ein Konto mit dieser Adresse existiert, erhältst du eine E-Mail zum Zurücksetzen.';

// Tokens are generated by Supabase Auth and delivered only to the account owner.
// No token or account-existence detail is ever returned to the caller.
export async function POST(request: NextRequest) {
  const origin = request.headers.get('origin');
  const allowedOrigins = new Set(['https://www.darkcharts.de', 'https://darkcharts.de']);
  if (origin && !allowedOrigins.has(origin)) {
    return NextResponse.json({ error: 'Origin not allowed' }, { status: 403 });
  }

  const limited = applyRateLimit(request, { windowMs: 15 * 60_000, maxRequests: 5 });
  if (limited) return limited;

  let json: unknown;
  try { json = await request.json(); }
  catch { return NextResponse.json({ error: 'Invalid request' }, { status: 400 }); }
  const parsed = bodySchema.safeParse(json);
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid email address' }, { status: 400 });
  }

  if (!process.env.RESEND_API_KEY?.startsWith('re_') || !process.env.EMAIL_FROM) {
    logger.error('Recovery email service is not configured');
    return NextResponse.json({ error: 'E-Mail-Versand ist derzeit nicht verfügbar.' }, { status: 503 });
  }

  const email = parsed.data.email.trim().toLowerCase();
  try {
    const db = createServiceRoleSupabaseClient();
    const { data, error } = await db.auth.admin.generateLink({
      type: 'recovery',
      email,
    });
    if (error) {
      // Supabase can report an unknown user here; preserve a uniform response.
      logger.warn('Recovery link generation was not completed', { code: error.code });
      return NextResponse.json({ success: true, message: GENERIC_MESSAGE });
    }
    const tokenHash = data?.properties?.hashed_token;
    if (tokenHash) {
      const url = new URL('/auth/confirm', 'https://www.darkcharts.de');
      url.searchParams.set('token_hash', tokenHash);
      url.searchParams.set('type', 'recovery');
      const resetLink = url.toString();
      await sendEmail({
        to: email,
        subject: 'darkcharts – Passwort zurücksetzen',
        html: `<!doctype html><html lang="de"><body style="background:#0d0d1a;color:#f3f0ff;font-family:Arial,sans-serif;padding:32px 16px">
        <main style="max-width:520px;margin:auto;padding:32px;background:#1a1a2e;border:1px solid #333052;border-radius:12px">
        <p style="color:#c4a1ff;font-size:12px;letter-spacing:2px;font-weight:bold">DARKCHARTS / ACCOUNT SECURITY</p>
        <h1 style="font-size:26px">Passwort zurücksetzen</h1>
        <p style="line-height:1.7;color:#c8c2d8">Für dein Konto wurde eine Passwortänderung angefragt. Wenn du das warst, kannst du ein neues Passwort vergeben.</p>
        <p style="margin:30px 0"><a href="${resetLink}" style="display:inline-block;color:white;background:#7134d3;padding:14px 20px;border-radius:6px;text-decoration:none;font-weight:bold">Neues Passwort festlegen</a></p>
        <p style="font-size:13px;line-height:1.6;color:#ada6c0">Du hast diese Änderung nicht angefragt? Dann ignoriere diese Nachricht. Dein Passwort bleibt unverändert.</p>
        </main></body></html>`,
      });
    }
  } catch (error) {
    // Do not log the email, recovery URL, or secret token.
    logger.error('Password recovery delivery failed', {
      error: error instanceof Error ? error.message : 'Unknown email service error',
    });
    return NextResponse.json({ error: 'E-Mail-Versand derzeit nicht verfügbar.' }, { status: 503 });
  }
  return NextResponse.json({ success: true, message: GENERIC_MESSAGE }, {
    headers: { 'Cache-Control': 'no-store' },
  });
}
